<?php require_once __DIR__.'/../includes/layout.php';if(empty($_SESSION['patient'])){header('Location: /portal/login.php');exit;}$p=passport($_SESSION['patient']);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(strlen($_POST['new_pin'])<4) $err='PIN must be at least 4 digits.';else{db()->prepare('UPDATE patients SET pin_hash=? WHERE patient_id=?')->execute([password_hash($_POST['new_pin'],PASSWORD_BCRYPT),$p['patient_id']]);audit('change_pin','patients',$p['patient_id'],null,'patient',$p['id']);$ok='PIN changed.';}}$q=db()->prepare('SELECT * FROM visits WHERE patient_id=? ORDER BY visit_date DESC');$q->execute([$p['patient_id']]);$v=$q->fetchAll();head('My Record');?><main class="portal"><div class="portal-head"><b>ThalVital</b><a style="float:right;color:#fff" href="/portal/logout.php">Sign out</a></div><h2><?=h($p['full_name'])?></h2><p class="muted"><code><?=h($p['patient_id'])?></code> · <?=h($p['org_name'])?></p><?php passport_card($p,true);?><section class="card"><label>Next due</label><h2><?=h($v[0]['next_due']??'Not scheduled')?></h2></section><section class="card"><h2>Hb trend</h2><canvas id="hb"></canvas><script>new Chart(hb,{type:'line',data:{labels:<?=json_encode(array_column($v,'visit_date'))?>,datasets:[{label:'Pre Hb',data:<?=json_encode(array_column($v,'pre_hb'))?>,borderColor:'#0D6B85'}]}})</script></section><section class="card"><h2>Visit history</h2><?php foreach($v as $x):?><div class="result-row"><span><?=h($x['visit_date'])?><br><small><?=h($x['pre_hb'])?> → <?=h($x['post_hb'])?> Hb</small></span><b><?=h($x['units_given'])?> units</b></div><?php endforeach?></section><section class="card"><h2>Change PIN</h2><?php if(!empty($ok))echo '<p class="tag">'.$ok.'</p>';if(!empty($err))echo '<p class="alert">'.$err.'</p>';?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input name="new_pin" type="password" placeholder="New PIN" required><br><br><button>Change PIN</button></form></section></main><?php footer();
